#!/usr/bin/env python
"""
Transform function for task-4a506e6c
Demonstrates observed transformation patterns from DEMO

Wave propagation rule: Horizontal propagation of boundary value (9) into 7-zones
with marking of propagation boundaries using value 4.
"""

def horizontal_propagate(grid):
    """
    Transform grid with wave propagation pattern.
    Returns first 28 rows of transformed grid.
    """
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    boundary, background = 9, 7

    for r in range(h):
        row_in = grid[r]
        c = 0
        while c < w:
            if row_in[c] == background and c > 0 and row_in[c-1] == boundary:
                start, end = c, c
                while end < w and row_in[end] == background:
                    end += 1
                if end < w and row_in[end] == boundary:
                    wave_dir = (r - 22) % 2
                    if wave_dir == 0:
                        for k in range(start, end):
                            if result[r][k] == background:
                                result[r][k] = boundary
            c += 1

    return result[:28]


